verdicts = []
for f in d["functions"]:
    a = f["address"]
    v, name, rel, own, reason, comment = F.pop(a)
    rel = rel or f["relation"]
    row = {"kind": "function", "firmware": "both" if rel == "twin" else "CM550", "address": a, "verdict": v,
           "final_name": name or f["proposed_name"], "final_relation": rel, "own_role": own, "reason": reason,
           "final_comment": comment, "final_cm848_address": f["cm848_address"] if rel == "twin" else "", "final_type": ""}
    verdicts.append(row)
for g in d["globals"]:
    a = g["address"]
    v, name, typ, reason, comment = G.pop(a)
    verdicts.append({"kind": "global", "firmware": "CM550", "address": a, "verdict": v, "final_name": name or g["proposed_name"],
                     "final_type": typ or g["proposed_type"], "reason": reason, "final_comment": comment})
for e in d["enum_members"]:
    v, name, reason, comment = E.pop(int(e["value"]))
    verdicts.append({"kind": "enum_member", "firmware": e["firmware"], "address": f"FUELING_STATE:{int(e['value'])}", "verdict": v,
                     "final_name": name or e["proposed_member"], "reason": reason, "final_comment": comment, "final_type": ""})
assert not F and not G and not E, (F.keys(), G.keys(), E.keys())
json.dump(verdicts, open(f"{R}/scratch/F1/judge/verdicts_f1.json", "w"), indent=1)
from collections import Counter
print(len(verdicts), Counter((v["kind"], v["verdict"]) for v in verdicts))
